19	    .status { font-weight: 600; }
20	  </style>
21	</head>
22	<body>
23	  <h1>Job tracker</h1>
24	
25	  <form data-testid="job-form" id="job-form" autocomplete="off">
26	    <label>Input
27	      <input data-testid="job-input" name="input" type="text">
28	    </label>
29	    <label>Steps
30	      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
31	    </label>
32	    <label>Fail attempts
33	      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
34	    </label>
35	    <button data-testid="job-submit" type="submit">Submit job</button>
36	  </form>
37	
38	  <div data-testid="form-error" role="alert" id="form-error"></div>
39	
40	  <ul data-testid="job-list" id="job-list"></ul>
41	
42	  <script>
43	    const form = document.getElementById('job-form');
44	    const errorBox = document.getElementById('form-error');
45	    const list = document.getElementById('job-list');
46	    const items = new Map();
47	    const NUMERIC = /^\s*-?\d+(\.\d+)?\s*$/;
48	
49	    // Numeric text goes out as a number so the API validates it; anything else is sent as typed,
50	    // and the API rejects it with the field named. Empty fields are omitted so defaults apply.
51	    function fieldValue(raw) {
52	      if (raw.trim() === '') return undefined;
53	      return NUMERIC.test(raw) ? Number(raw) : raw;
54	    }
55	
56	    function setError(text) {
57	      errorBox.textContent = text;
58	    }
59	
60	    form.addEventListener('submit', async (event) => {
61	      event.preventDefault();
62	      const data = new FormData(form);
63	      const body = { input: data.get('input') };
64	      const steps = fieldValue(data.get('steps'));
65	      const failAttempts = fieldValue(data.get('failAttempts'));
66	      if (steps !== undefined) body.steps = steps;
67	      if (failAttempts !== undefined) body.failAttempts = failAttempts;
68	
69	      const submit = document.querySelector('[data-testid="job-submit"]');
70	      submit.disabled = true;
71	      try {
72	        const res = await fetch('/api/jobs', {
73	          method: 'POST',
74	          headers: { 'content-type': 'application/json' },
75	          body: JSON.stringify(body),
76	        });
77	        const payload = await res.json().catch(() => null);
78	        if (res.ok) {
79	          setError('');
80	          form.elements.input.value = '';
81	          await refresh();
82	        } else if (payload && payload.error) {
83	          const fields = Array.isArray(payload.error.fields)
84	            ? payload.error.fields.map((f) => `${f.field}: ${f.message}`).join('; ')
85	            : '';
86	          setError(fields ? `${payload.error.message} ${fields}` : payload.error.message);
87	        } else {
88	          setError(`Submission failed (HTTP ${res.status}).`);
89	        }
90	      } catch (e) {
91	        setError(`Submission failed: ${e.message}`);
92	      } finally {
93	        submit.disabled = false;
94	      }
95	    });
96	
97	    function createItem(id) {
98	      const li = document.createElement('li');
99	      li.setAttribute('data-testid', 'job-item');
100	      li.setAttribute('data-job-id', id);
101	      const meta = document.createElement('span');
102	      meta.className = 'meta';
103	      const status = document.createElement('span');
104	      status.className = 'status';
105	      status.setAttribute('data-testid', 'job-status');
106	      const progress = document.createElement('span');
107	      progress.setAttribute('data-testid', 'job-progress');
108	      const result = document.createElement('span');
109	      result.setAttribute('data-testid', 'job-result');
110	      li.append(meta, status, progress, result);
111	      return li;
112	    }
113	
114	    function updateItem(li, job) {
115	      li.querySelector('.meta').textContent = `Input: ${job.input}`;
116	      li.querySelector('[data-testid="job-status"]').textContent = job.status;
117	      li.querySelector('[data-testid="job-progress"]').textContent = `${job.progress.completed}/${job.progress.total}`;
118	      let text = '';
119	      if (job.status === 'completed' && job.result) text = job.result.output;
120	      else if (job.status === 'failed' && job.error) text = job.error;
121	      li.querySelector('[data-testid="job-result"]').textContent = text;
122	    }
123	
124	    function render(jobs) {
125	      const seen = new Set();
126	      jobs.forEach((job, index) => {
127	        let li = items.get(job.id);
128	        if (!li) {
129	          li = createItem(job.id);
130	          items.set(job.id, li);
131	        }
132	        updateItem(li, job);
133	        seen.add(job.id);
134	        if (list.children[index] !== li) list.insertBefore(li, list.children[index] || null);
135	      });
136	      for (const [id, li] of items) {
137	        if (!seen.has(id)) {
138	          li.remove();
139	          items.delete(id);
140	        }
141	      }
142	    }
143	
144	    async function refresh() {
145	      try {
146	        const res = await fetch('/api/jobs');
147	        if (!res.ok) return;
148	        const body = await res.json();
149	        render(body.jobs);
150	      } catch {
151	        // the next poll retries
152	      }
153	    }
154	
155	    refresh();
156	    setInterval(refresh, 1000);
157	  </script>
158	</body>
